do $$declare op text;s text;needle text:='a.id=r.analyst_id), totals';begin foreach op in array array['qa','pqr'] loop select pg_get_functiondef(('private.'||op||'_operation_report()')::regprocedure) into s;if strpos(s,needle)>0 then execute replace(s,needle,$r$a.id=r.analyst_id where r.status='completed'), totals$r$);elsif strpos(s,$r$where r.status='completed'), totals$r$)=0 then raise exception 'No se encontro alcance del reporte %',op;end if;end loop;end;$$;
